/** Escapes every visitor-controlled value before inserting it into HTML email. */
export function escapeHtml(value) {
  return value.replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
}

/** Creates an inbox-friendly HTML template plus a plain-text accessibility fallback. */
